const v1Configs = tool("configs", {});
const v2Configs = [];

for (const cfg of v1Configs) {
  // timeout -> timeoutMs (bare number = seconds)
  let timeoutMs = 0;
  const rawTimeout = cfg.timeout;
  if (typeof rawTimeout === "number") {
    timeoutMs = Math.round(rawTimeout * 1000);
  } else if (rawTimeout !== undefined && rawTimeout !== null) {
    const m = String(rawTimeout).trim().match(/^(\d+(?:\.\d+)?)\s*(ms|s|m)?$/);
    if (m) {
      const value = parseFloat(m[1]);
      const unit = m[2] || "s";
      if (unit === "ms") {
        timeoutMs = Math.round(value);
      } else if (unit === "m") {
        timeoutMs = Math.round(value * 60 * 1000);
      } else {
        timeoutMs = Math.round(value * 1000);
      }
    }
  }

  // endpoint -> host, port (443 when no port)
  let host = "";
  let port = 443;
  const rawEndpoint = String(cfg.endpoint == null ? "" : cfg.endpoint).trim();
  const colonIndex = rawEndpoint.lastIndexOf(":");
  const maybePort = colonIndex >= 0 ? rawEndpoint.slice(colonIndex + 1) : "";
  if (colonIndex > 0 && /^\d+$/.test(maybePort)) {
    host = rawEndpoint.slice(0, colonIndex);
    port = parseInt(maybePort, 10);
  } else {
    host = rawEndpoint;
  }

  // retries (0 when missing)
  let retries = 0;
  if (cfg.retries !== undefined && cfg.retries !== null && cfg.retries !== "") {
    const parsedRetries = parseInt(cfg.retries, 10);
    if (!isNaN(parsedRetries)) {
      retries = parsedRetries;
    }
  }

  // tags: lowercase, trimmed, de-duplicated, sorted ascending
  let rawTags = [];
  if (typeof cfg.tags === "string") {
    rawTags = cfg.tags.split(",");
  } else if (Array.isArray(cfg.tags)) {
    rawTags = cfg.tags;
  }
  const seenTags = {};
  const tags = [];
  for (const rawTag of rawTags) {
    const tag = String(rawTag).trim().toLowerCase();
    if (tag === "" || seenTags[tag]) {
      continue;
    }
    seenTags[tag] = true;
    tags.push(tag);
  }
  tags.sort();

  // enabled
  let enabled = false;
  const rawEnabled = cfg.enabled;
  if (
    rawEnabled === true ||
    rawEnabled === 1 ||
    rawEnabled === "yes" ||
    rawEnabled === "true" ||
    rawEnabled === "on"
  ) {
    enabled = true;
  }

  // priority: judgment call, ask the model once per config
  const priority = tool("judge", {
    question:
      "A service owner wrote a note about their service. Classify its priority. " +
      "urgent: an outage would hurt customers, revenue or login, or it needs someone woken up. " +
      "low: nobody depends on it, experimental, legacy or best effort. " +
      "normal: everything else. Answer with exactly one word.",
    options: ["urgent", "normal", "low"],
    text: cfg.owner_note == null ? "" : String(cfg.owner_note)
  });

  v2Configs.push({
    name: cfg.name,
    timeoutMs: timeoutMs,
    host: host,
    port: port,
    retries: retries,
    tags: tags,
    enabled: enabled,
    priority: priority
  });
}

v2Configs;
